document.querySelector('#submitPin').addEventListener('click',async()=>{const titleValue=document.querySelector('#pinTitle').value.trim();const descriptionValue=document.querySelector('#pinDescription').value.trim();if(!titleValue||!descriptionValue){toast(language==='ko'?'이름과 설명을 입력해주세요.':'Please enter a title and description.');return}const center=pinLocation||vectorMap.getCenter();const amenities=[...document.querySelectorAll('.amenity-options input:checked')].map(input=>input.value);const response=await fetch('api/pins',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({deviceId,type:document.querySelector('#pinType').value,title:titleValue,description:descriptionValue,locationHint:document.querySelector('#pinLocationHint').value.trim(),amenities,lat:center.lat,lon:center.lng})});const result=await response.json();if(!response.ok){toast(result.reason||'핀을 등록할 수 없어요.');return}pinRecords.push(result);renderPins();document.querySelector('#pinComposer').hidden=true;document.querySelector('#pinTitle').value='';document.querySelector('#pinLocationHint').value='';document.querySelector('#pinDescription').value='';document.querySelectorAll('.amenity-options input').forEach(input=>input.checked=false);pinLocation=null;vectorMap.flyTo([result.lat,result.lon],Math.max(vectorMap.getZoom(),17),{duration:.6});toast(language==='ko'?'핀이 톡 떨어졌어요.':'Your pin landed on the map.')});updateFacilityFields();
const oldSubmitPin=document.querySelector('#submitPin');const cleanSubmitPin=oldSubmitPin.cloneNode(true);oldSubmitPin.replaceWith(cleanSubmitPin);cleanSubmitPin.addEventListener('click',async()=>{const titleValue=document.querySelector('#pinTitle').value.trim();const descriptionValue=document.querySelector('#pinDescription').value.trim();if(!titleValue||!descriptionValue){toast(language==='ko'?'이름과 설명을 입력해주세요.':'Please enter a title and description.');return}const center=pinLocation||vectorMap.getCenter();const amenities=[...document.querySelectorAll('.amenity-options input:checked')].map(input=>input.value);const response=await fetch('api/pins',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({deviceId,type:document.querySelector('#pinType').value,title:titleValue,description:descriptionValue,locationHint:document.querySelector('#pinLocationHint').value.trim(),amenities,lat:center.lat,lon:center.lng})});const result=await response.json();if(!response.ok){toast(result.reason||'핀을 등록할 수 없어요.');return}pinRecords.push(result);renderPins();document.querySelector('#pinComposer').hidden=true;document.querySelector('#pinTitle').value='';document.querySelector('#pinLocationHint').value='';document.querySelector('#pinDescription').value='';document.querySelectorAll('.amenity-options input').forEach(input=>input.checked=false);pinLocation=null;vectorMap.flyTo([result.lat,result.lon],Math.max(vectorMap.getZoom(),17),{duration:.6});toast(language==='ko'?'핀이 톡 떨어졌어요.':'Your pin landed on the map.')});
Object.assign(copy.ko,{locationSuggest:'핀마다 위치가 달라요',locationWarning:'위치 확인 필요',suggestionDone:'위치 제안이 접수되었어요.'});Object.assign(copy.en,{locationSuggest:'Suggest a location',locationWarning:'Location needs review',suggestionDone:'Location suggestion received.'});let suggestions=[];const suggestionLayer=L.layerGroup().addTo(vectorMap);let suggestingSpot=null;function suggestionCount(spot){return suggestions.filter(item=>item.spotId===spot.id).length}function spotBubbleWithSuggestion(spot){const count=suggestionCount(spot);return `<article class="spot-bubble"><span class="spot-badge">${escapeHtml(spotTypes[spot.type])}</span>${count>=3?`<small class="location-warning">${copy[language].locationWarning}</small>`:''}<h3>${escapeHtml(spotName(spot))}</h3><p>${escapeHtml(localizedName(spot.nearbyBuilding))}</p><small>${language==='ko'?'대략 위치':'Approximate location'}</small><button class="spot-suggest-action">${copy[language].locationSuggest}</button></article>`}function showSpotSuggestions(spot){suggestionLayer.clearLayers();suggestions.filter(item=>item.spotId===spot.id).forEach(item=>L.circleMarker([item.lat,item.lon],{radius:4,color:'#f18b42',fillColor:'#f18b42',fillOpacity:.9,weight:2}).addTo(suggestionLayer))}function startSpotSuggestion(spot){suggestingSpot=spot;startPinPicker();toast(language==='ko'?'지도를 움직여 정확한 위치를 맞춰주세요.':'Move the map to the correct location.')}function finishSpotSuggestion(){const center=vectorMap.getCenter();return fetch('api/spot-suggestions',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({spotId:suggestingSpot.id,deviceId,lat:center.lat,lon:center.lng})}).then(async response=>{const result=await response.json();if(!response.ok){toast(result.reason||'위치를 제안할 수 없어요.');return}suggestions.push(result);stopPinPicker();suggestingSpot=null;renderSpots();toast(result.needsVerification?copy[language].locationWarning:copy[language].suggestionDone)})}
const oldConfirmLocation=document.querySelector('#confirmLocation');const cleanConfirmLocation=oldConfirmLocation.cloneNode(true);oldConfirmLocation.replaceWith(cleanConfirmLocation);cleanConfirmLocation.addEventListener('click',()=>{if(suggestingSpot){finishSpotSuggestion();return}pinLocation=vectorMap.getCenter();stopPinPicker();document.querySelector('#pinComposer').hidden=false;updateFacilityFields()});fetch('api/spot-suggestions').then(response=>response.json()).then(data=>{suggestions=Array.isArray(data)?data:[];renderSpots()}).catch(()=>{});
renderSpotsPanel=function(){const visible=spots.filter(spot=>spotFilter==='all'||spot.type===spotFilter);const grouped=Object.entries(spotTypes).filter(([key])=>key!=='all').map(([key,label])=>[key,label,visible.filter(spot=>spot.type===key)]).filter(([, ,items])=>items.length);panel.querySelector('.panel-content').innerHTML=`<div class="spot-filters">${Object.entries(spotTypes).map(([key,label])=>`<button class="spot-filter ${spotFilter===key?'active':''}" data-spot-filter="${key}">${label}</button>`).join('')}</div><div class="spot-list-note">${visible.length}${language==='ko'?'곳':' places'}</div><div class="spot-list">${grouped.map(([key,label,items])=>`<section class="spot-group"><h3>${label}<b>${items.length}</b></h3>${items.map(spot=>`<button class="spot-card" data-spot-id="${spot.id}"><span class="spot-list-icon spot-${spot.type}">${spotIcons[spot.type]||'·'}</span><span><strong>${escapeHtml(spotName(spot))}</strong><small>${escapeHtml(localizedName(spot.nearbyBuilding))}</small><em>${label} · ${language==='ko'?'대략 위치':'Approximate location'}</em></span><b>›</b></button>`).join('')}</section>`).join('')}</div>`;panel.querySelectorAll('[data-spot-filter]').forEach(button=>button.addEventListener('click',()=>{spotFilter=button.dataset.spotFilter;renderSpotsPanel();renderSpots()}));panel.querySelectorAll('[data-spot-id]').forEach(card=>card.addEventListener('click',()=>{const spot=spots.find(item=>item.id===card.dataset.spotId);if(spot){vectorMap.flyTo([spot.location.lat,spot.location.lon],17,{duration:.7});showSpotSuggestions(spot);spotMarkers.find(marker=>marker.getLatLng().lat===spot.location.lat&&marker.getLatLng().lng===spot.location.lon)?.openPopup()}}))};
spotIcon=function(spot){const warning=typeof suggestions!=='undefined'&&suggestionCount(spot)>=3?'<i class="spot-warning">!</i>':'';return L.divIcon({className:`spot-marker spot-${spot.type}`,html:`<span>${spotIcons[spot.type]||'·'}</span>${warning}`,iconSize:[28,28],iconAnchor:[14,14],popupAnchor:[0,-12]})};
const today='2026-09-17';let eventData=null;let selectedInstitutionId=null;const eventLayer=L.layerGroup().addTo(vectorMap);const statusLabels={ko:{ongoing:'진행중',upcoming:'예정',ended:'종료'},en:{ongoing:'Ongoing',upcoming:'Upcoming',ended:'Ended'}};function eventStatus(event){const dates=(event.period||'').match(/\d{4}-\d{2}-\d{2}/g)||[];const start=dates[0]||event.noticeDate;const end=dates[1]||dates[0]||event.noticeDate;if(start>today)return'upcoming';if(end<today)return'ended';return'ongoing'}function eventDate(event){return event.period||event.noticeDate||'기간 미정'}function activeEventCount(institution){return institution.events.filter(event=>{const status=eventStatus(event);return status==='ongoing'||status==='upcoming'}).length}function eventMarkerIcon(count){return L.divIcon({className:'event-office-marker',html:`<span>${count}</span>`,iconSize:[36,36],iconAnchor:[18,18]})}
function renderEventMarkers(){eventLayer.clearLayers();if(!eventData)return;eventData.institutions.forEach(institution=>{const center=institution.office?.building?.center;if(!center)return;const marker=L.marker(center,{icon:eventMarkerIcon(activeEventCount(institution)),zIndexOffset:300});marker.on('click',()=>{selectedInstitutionId=institution.id;activePanel=null;openPanel('news');vectorMap.flyTo(center,17,{duration:.7})});marker.addTo(eventLayer)})}
function highlightOffice(institution){const building=institution.office?.building;const layer=layers.buildings.find(item=>item.options.radarBuildingId===building?.osmId);if(!layer)return;vectorMap.flyTo(building.center,17,{duration:.7});const element=layer.getElement();element?.classList.remove('building-highlight');void element?.offsetWidth;element?.classList.add('building-highlight');window.setTimeout(()=>element?.classList.remove('building-highlight'),2200)}
function shortInstitutionName(item){return({rise:'RISE', 'du-huss':'HUSS',library:'창파도서관',university:'본관',aisw:'SW'})[item.id]||localizedName(item.name)}
function renderNewsPanel(){if(!eventData)return;const institution=eventData.institutions.find(item=>item.id===selectedInstitutionId)||eventData.institutions[0];selectedInstitutionId=institution.id;const events=[...institution.events].sort((a,b)=>{const rank={ongoing:0,upcoming:1,ended:2};return rank[eventStatus(a)]-rank[eventStatus(b)]||b.noticeDate.localeCompare(a.noticeDate)});panel.querySelector('.panel-content').innerHTML=`<div class="institution-pills">${eventData.institutions.map(item=>`<button class="institution-pill ${item.id===institution.id?'active':''}" data-institution="${item.id}">${shortInstitutionName(item)}<b>${activeEventCount(item)}</b></button>`).join('')}</div><div class="institution-card"><div><span>${language==='ko'?'기관':'Institution'}</span><h2>${escapeHtml(localizedName(institution.name))}</h2><p>${escapeHtml(institution.office.room||institution.office.building.name[language]||institution.office.building.name.ko)}</p></div><div class="institution-actions"><button class="office-jump" data-institution="${institution.id}">${language==='ko'?'사무실 위치':'Office location'} ↗</button><a href="${institution.website}" target="_blank" rel="noopener">${language==='ko'?'홈페이지':'Website'} ↗</a></div></div><div class="event-list">${events.map(event=>{const status=eventStatus(event);return`<article class="event-card ${status}"><div class="event-card-top"><span class="event-status ${status}">${statusLabels[language][status]}</span><span>${escapeHtml(institution.name[language]||institution.name.ko)}</span></div><h3>${escapeHtml(event.title[language]||event.title.ko)}</h3><dl><div><dt>${language==='ko'?'기간':'When'}</dt><dd>${escapeHtml(eventDate(event))}</dd></div><div><dt>${language==='ko'?'장소':'Where'}</dt><dd>${escapeHtml(event.location?.[language]||event.location?.ko||'장소 미정')}</dd></div></dl><p>${escapeHtml(event.summary[language]||event.summary.ko)}</p>${event.applicationDeadline?`<small class="event-deadline">${language==='ko'?'신청 마감':'Deadline'} · ${escapeHtml(event.applicationDeadline)}</small>`:''}<a class="event-source" href="${event.originalLink}" target="_blank" rel="noopener">${language==='ko'?'원문 보기':'View source'} ↗</a></article>`}).join('')}</div><p class="event-source-note">${language==='ko'?'출처 · 기관별 공식 홈페이지 공지사항':'Sources · Official institution notice pages'}</p>`;panel.querySelectorAll('[data-institution]').forEach(button=>button.addEventListener('click',()=>{selectedInstitutionId=button.dataset.institution;renderNewsPanel()}));panel.querySelector('.office-jump')?.addEventListener('click',()=>highlightOffice(institution))}
const openPanelWithSpots=openPanel;openPanel=function(name){if(name==='news'){if(activePanel===name&&panel.classList.contains('open')){closePanel();return}activePanel='news';title.textContent=copy[language].news;panel.classList.add('open');panel.classList.toggle('sheet-low',window.innerWidth<760);document.querySelectorAll('[data-panel]').forEach(el=>el.classList.toggle('active',el.dataset.panel===name));renderNewsPanel();return}openPanelWithSpots(name)};new MutationObserver(()=>{if(activePanel==='news')renderNewsPanel()}).observe(document.documentElement,{attributes:true,attributeFilter:['data-language','data-theme']});
fetch('data/events.json').then(response=>response.json()).then(data=>{eventData=data;dedupeEventLists(data);data.institutions.forEach(institution=>{const building=institution.office?.building;const override=building&&buildingNameOverrides[building.name?.ko||building.ko];if(override)Object.assign(building,override);building.name={ko:building.ko,en:building.en}});selectedInstitutionId=null;renderEventMarkers();if(window.innerWidth<760){openPanel('news');panel.classList.add('sheet-low')}else openPanel('news')}).catch(error=>console.error('DU Radar events failed',error));
let seedPinRecords=[];let seedLostItems=[];let officesData=null;let lostFilter='all';let routeMode=false;let routeTarget=null;let routePoints=[];const routeLayer=L.layerGroup().addTo(vectorMap);const routePointLayer=L.layerGroup().addTo(vectorMap);const lostKinds={lost:'잃어버림',found:'주움'};const itemEnglish={이어폰:'earbuds',학생증:'student ID',지갑:'wallet',우산:'umbrella',텀블러:'tumbler',충전기:'charger',필통:'pencil case',기타:'item'};
function lostText(item,field){if(language==='en'&&item[`${field}En`])return item[`${field}En`];if(language==='en'&&field==='title'&&item.category)return`${item.kind==='found'?'Found':'Lost'} ${itemEnglish[item.category]||'item'}`;if(language==='en'&&field==='description')return`A ${itemEnglish[item.category]||'item'} ${item.kind==='found'?'was found':'was lost'} near ${item.location?.label||'campus'}.`;return item[field]||''}function lostItems(){return[...seedLostItems,...pinRecords.filter(pin=>pin.type==='lost').map(pin=>({...pin,kind:pin.lostKind||'lost',category:pin.category||'기타',location:{lat:pin.lat,lon:pin.lon,label:pin.locationHint||'캠퍼스'}}))]}
function distanceMeters(a,b){const R=6371000,p=Math.PI/180,la=a[0]*p,lb=b[0]*p,dy=(b[0]-a[0])*p,dx=(b[1]-a[1])*p;return 2*R*Math.asin(Math.sqrt(Math.sin(dy/2)**2+Math.cos(la)*Math.cos(lb)*Math.sin(dx/2)**2))}function nearestOffice(lat,lon){if(!officesData)return null;return officesData.offices.map(office=>({...office,distance:distanceMeters([lat,lon],office.matchedBuilding.center)})).sort((a,b)=>a.distance-b.distance)[0]}
function officeCard(item){const office=nearestOffice(item.location.lat,item.location.lon);if(!office)return'';const found=item.kind==='found';return`<section class="lost-office"><span>${language==='en'?'Nearest office':'가까운 단과대학 행정실'}</span><h3>${escapeHtml(localizedName(office.name))}</h3><p>${escapeHtml(office.matchedBuilding.name[language]||office.matchedBuilding.name.ko)} · ${escapeHtml(office.room)} · ${Math.round(office.distance)}m</p>${office.locationNeedsReview?`<small class="office-review">${language==='en'?'Location needs review':'위치 확인 필요'}</small>`:''}<strong>${found?(language==='en'?'You can leave it here.':'여기에 맡기면 돼요.'): (language==='en'?'Ask here first.':'여기에 먼저 물어보세요.')}</strong><button class="lost-office-map" data-office-id="${office.id}">${language==='en'?'View on map':'지도에서 보기'} ↗</button></section>`}
function renderLostPanel(){const items=lostItems().filter(item=>lostFilter==='all'||item.kind===lostFilter).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));panel.querySelector('.panel-content').innerHTML=`<div class="lost-filters"><button class="lost-filter ${lostFilter==='all'?'active':''}" data-lost-filter="all">${language==='en'?'All':'전체'}</button><button class="lost-filter ${lostFilter==='lost'?'active':''}" data-lost-filter="lost">${language==='en'?'Lost':'잃어버림'}</button><button class="lost-filter ${lostFilter==='found'?'active':''}" data-lost-filter="found">${language==='en'?'Found':'주움'}</button></div><div class="lost-count">${items.length}${language==='en'?' posts':'개'}</div><div class="lost-list">${items.map(item=>`<button class="lost-card" data-lost-id="${item.id}"><div class="lost-card-top"><span class="lost-kind ${item.kind}">${lostKinds[item.kind]||item.kind}</span><span>${escapeHtml(item.category||'기타')}</span><time>${pinTime(item.createdAt)}</time></div><h3>${escapeHtml(lostText(item,'title'))}</h3><p>${escapeHtml(item.location?.label||'캠퍼스')}</p><small>${escapeHtml(lostText(item,'description'))}</small></button>`).join('')}</div>`;panel.querySelectorAll('[data-lost-filter]').forEach(button=>button.addEventListener('click',()=>{lostFilter=button.dataset.lostFilter;renderLostPanel();renderPins()}));panel.querySelectorAll('[data-lost-id]').forEach(card=>card.addEventListener('click',()=>{const item=items.find(entry=>entry.id===card.dataset.lostId);if(item)showLostItem(item)}));}
function showLostItem(item){activePanel='lost';title.textContent=copy[language].lost;panel.classList.add('open');panel.querySelector('.panel-content').innerHTML=`<article class="lost-detail"><div class="lost-detail-top"><span class="lost-kind ${item.kind}">${lostKinds[item.kind]||item.kind}</span><span>${escapeHtml(item.category||'기타')}</span></div><h2>${escapeHtml(lostText(item,'title'))}</h2><p>${escapeHtml(lostText(item,'description'))}</p><time>${escapeHtml(item.location?.label||'캠퍼스')} · ${pinTime(item.createdAt)}</time>${officeCard(item)}${item.kind==='lost'?`<button class="lost-route-button">${language==='en'?'I do not know where I lost it':'잃어버린 곳을 모르겠어요'}</button>`:''}</article>`;panel.querySelector('.lost-office-map')?.addEventListener('click',()=>{const office=nearestOffice(item.location.lat,item.location.lon);if(office)highlightOffice({office})});panel.querySelector('.lost-route-button')?.addEventListener('click',()=>startLostRoute(item));vectorMap.flyTo([item.location.lat,item.location.lon],17,{duration:.7});document.querySelectorAll('[data-panel]').forEach(el=>el.classList.toggle('active',el.dataset.panel==='lost'))}
function highlightOffice(record){const building=record.office?.building||record.building||record.office?.matchedBuilding;const layer=layers.buildings.find(item=>item.options.radarBuildingId===building?.osmId);if(!layer||!building?.center)return;vectorMap.flyTo(building.center,17,{duration:.7});const element=layer.getElement();element?.classList.remove('building-highlight');void element?.offsetWidth;element?.classList.add('building-highlight');setTimeout(()=>element?.classList.remove('building-highlight'),2200)}
function routeDistance(item){return Math.min(...routePoints.map(point=>distanceMeters([item.location.lat,item.location.lon],[point.lat,point.lng])))}function routeOfficeDistance(office){return Math.min(...routePoints.map(point=>distanceMeters([office.matchedBuilding.center[0],office.matchedBuilding.center[1]],[point.lat,point.lng])))}function routeResults(){const targetCategory=routeTarget.category;const now=Date.parse(routeTarget.createdAt);const matches=lostItems().filter(item=>item.kind==='found'&&item.category===targetCategory&&item.id!==routeTarget.id).map(item=>({...item,distance:routeDistance(item),hours:Math.abs(now-Date.parse(item.createdAt))/3600000})).filter(item=>item.distance<=150&&item.hours<=72).sort((a,b)=>(a.distance+a.hours*20)-(b.distance+b.hours*20));const offices=officesData?.offices.map(office=>({...office,distance:routeOfficeDistance(office)})).filter(office=>office.distance<=150).sort((a,b)=>a.distance-b.distance)||[];panel.querySelector('.panel-content').innerHTML=`<article class="route-results"><div class="route-result-head"><span>${language==='en'?'Route search':'동선 찾기'}</span><button class="route-clear">${language==='en'?'Clear':'초기화'}</button></div><h2>${language==='en'?'Possible matches':'동선 근처에서 찾았어요.'}</h2><p>${language==='en'?'Matched found items within 150m and 3 days.':'동선 150m 안에서 같은 종류이고 3일 이내인 주운 물건이에요.'}</p><div class="route-match-list">${matches.length?matches.map(item=>`<button class="route-match" data-lost-id="${item.id}"><strong>${escapeHtml(lostText(item,'title'))}</strong><small>${Math.round(item.distance)}m · ${item.hours.toFixed(1)}시간 차이</small></button>`).join(''):`<span class="route-empty">${language==='en'?'No matching found items.':'조건에 맞는 주운 물건이 없어요.'}</span>`}</div><h3>${language==='en'?'Nearby offices':'동선 근처 행정실'}</h3><div class="route-office-list">${offices.map(office=>`<button class="route-office" data-office-id="${office.id}">${escapeHtml(localizedName(office.name))}<small>${Math.round(office.distance)}m · ${escapeHtml(office.room)}</small></button>`).join('')||`<span class="route-empty">${language==='en'?'No offices within 150m.':'150m 안에 행정실이 없어요.'}</span>`}</div></article>`;panel.querySelector('.route-clear').addEventListener('click',()=>startLostRoute(routeTarget));panel.querySelectorAll('[data-lost-id]').forEach(button=>button.addEventListener('click',()=>{const item=lostItems().find(entry=>entry.id===button.dataset.lostId);if(item)showLostItem(item)}));panel.querySelectorAll('[data-office-id]').forEach(button=>button.addEventListener('click',()=>{const office=offices.find(entry=>entry.id===button.dataset.officeId);if(office)highlightOffice({office})}))}
