vectorMap.on('click',event=>{if(!routeMode)return;routePoints.push(event.latlng);routeLayer.clearLayers();routePointLayer.clearLayers();L.polyline(routePoints,{color:'#5368f5',weight:3,dashArray:'6 7'}).addTo(routeLayer);routePoints.forEach((point,index)=>L.marker(point,{icon:L.divIcon({className:'route-step',html:String(index+1),iconSize:[22,22],iconAnchor:[11,11]})}).addTo(routePointLayer));document.querySelector('.route-points-count').textContent=`${routePoints.length}곳`});
