const reportCategories=['콘센트','빔프로젝터','에어컨','의자','와이파이','문','엘리베이터','기타'];const reportStatusLabels={접수:'접수',확인중:'확인중',수리완료:'수리완료','전달 대기':'전달 대기'};let faultSeedItems=[];let reactionCounts={};const reactedKey='du-radar-reactions';const reactedPins=JSON.parse(localStorage.getItem(reactedKey)||'[]');function reportCount(item){return Number(item.empathyCount||0)+Number(reactionCounts[item.id]||0)}function reportState(item){if(item.status==='수리완료')return'수리완료';return reportCount(item)>5?'전달 대기':item.status||'접수'}function reportItems(){return[...faultSeedItems,...pinRecords.filter(pin=>pin.type==='report'&&!pin.seed).map(pin=>({...pin,category:pin.category||'기타',status:pin.status||'접수',location:{lat:pin.lat,lon:pin.lon,label:pin.locationHint||'캠퍼스'}}))]}function reportOfficeBrief(item){const office=nearestOffice(item.location.lat,item.location.lon);if(!office)return'';return`<div class="report-office"><strong>가까운 행정실</strong><span>${escapeHtml(localizedName(office.name))} · ${escapeHtml(office.matchedBuilding[language]||office.matchedBuilding.ko)}</span><small>${escapeHtml(office.room)} · ${Math.round(office.distance)}m${office.locationNeedsReview?' · 위치 확인 필요':''}</small></div>`}function reportCard(item){const state=reportState(item),count=reportCount(item),waiting=state==='전달 대기';return`<article class="report-card ${state==='수리완료'?'completed':''} ${waiting?'waiting':''}"><div class="report-card-top"><span class="report-status ${state==='수리완료'?'completed':waiting?'waiting':'checking'}">${state}</span><span>${escapeHtml(item.category)}</span><time>${pinTime(item.createdAt)}</time></div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(item.location?.label||'캠퍼스')}</p><small>${escapeHtml(item.description)}</small>${waiting?reportOfficeBrief(item):''}<div class="report-card-bottom"><button class="reaction-button ${reactedPins.includes(item.id)?'reacted':''}" data-report-id="${item.id}" ${reactedPins.includes(item.id)?'disabled':''}>나도 겪었어요 <b>${count}</b></button>${!waiting&&state!=='수리완료'?`<em>전달까지 ${Math.max(0,6-count)}명</em>`:''}${waiting?'<em>행정실 전달 대기</em>':''}</div></article>`}function renderReportPanel(){const items=reportItems().sort((a,b)=>{const rank={'전달 대기':0,확인중:1,접수:2,수리완료:3};return rank[reportState(a)]-rank[reportState(b)]||Date.parse(b.createdAt)-Date.parse(a.createdAt)});const waiting=items.filter(item=>reportState(item)==='전달 대기').length;const checking=items.filter(item=>reportState(item)==='확인중').length;panel.querySelector('.panel-content').innerHTML=`<div class="report-summary"><div><b>${waiting}</b><span>전달 대기</span></div><div><b>${checking}</b><span>확인중</span></div></div><div class="report-list">${items.map(reportCard).join('')}</div>`;panel.querySelectorAll('.reaction-button').forEach(button=>button.addEventListener('click',()=>reactToReport(button.dataset.reportId)))}async function reactToReport(id){if(reactedPins.includes(id))return;const response=await fetch('api/reactions',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({pinId:id,deviceId})});const result=await response.json();if(!response.ok){toast(result.reason||'공감할 수 없어요.');return}reactionCounts[id]=result.count;reactedPins.push(id);localStorage.setItem(reactedKey,JSON.stringify(reactedPins));renderReportPanel();renderPins();toast('공감이 반영되었어요.')}
