officeCard=function(item){const office=nearestOffice(item.location.lat,item.location.lon);if(!office)return'';const found=item.kind==='found';return`<section class="lost-office"><span>${language==='en'?'Nearest office':'가까운 단과대학 행정실'}</span><h3>${escapeHtml(localizedName(office.name))}</h3><p>${escapeHtml(office.matchedBuilding[language]||office.matchedBuilding.ko)} · ${escapeHtml(office.room)} · ${Math.round(office.distance)}m</p>${office.locationNeedsReview?`<small class="office-review">${language==='en'?'Location needs review':'위치 확인 필요'}</small>`:''}<strong>${found?(language==='en'?'You can leave it here.':'여기에 맡기면 돼요.'): (language==='en'?'Ask here first.':'여기에 먼저 물어보세요.')}</strong><button class="lost-office-map" data-office-id="${office.id}">${language==='en'?'View on map':'지도에서 보기'} ↗</button></section>`};showLostItem=function(item){activePanel='lost';title.textContent=copy[language].lost;panel.classList.add('open');panel.querySelector('.panel-content').innerHTML=`<article class="lost-detail"><div class="lost-detail-top"><span class="lost-kind ${item.kind}">${lostKinds[item.kind]||item.kind}</span><span>${escapeHtml(item.category||'기타')}</span></div><h2>${escapeHtml(lostText(item,'title'))}</h2><p>${escapeHtml(lostText(item,'description'))}</p><time>${escapeHtml(item.location?.label||'캠퍼스')} · ${pinTime(item.createdAt)}</time>${officeCard(item)}${item.kind==='lost'?`<button class="lost-route-button">${language==='en'?'I do not know where I lost it':'잃어버린 곳을 모르겠어요'}</button>`:''}</article>`;panel.querySelector('.lost-office-map')?.addEventListener('click',()=>{const office=nearestOffice(item.location.lat,item.location.lon);if(office)highlightOffice({building:office.matchedBuilding})});panel.querySelector('.lost-route-button')?.addEventListener('click',()=>startLostRoute(item));vectorMap.flyTo([item.location.lat,item.location.lon],17,{duration:.7});document.querySelectorAll('[data-panel]').forEach(el=>el.classList.toggle('active',el.dataset.panel==='lost'))};
