fetch('data/campus-map.json').then(response=>response.json()).then(data=>{const areas=new Map(data.buildings.map(building=>{const lats=building.geometry.map(point=>point[0]),lons=building.geometry.map(point=>point[1]);return[building.osmId,(Math.max(...lats)-Math.min(...lats))*(Math.max(...lons)-Math.min(...lons))]}));layers.labels.forEach(label=>{const match=data.buildings.find(building=>building.center&&distanceMeters(building.center,[label.getLatLng().lat,label.getLatLng().lng])<8);label.options.buildingArea=match?areas.get(match.osmId)||0:0});refreshBuildingLabelsByArea()}).catch(()=>{});function refreshBuildingLabelsByArea(){const zoom=vectorMap.getZoom();const sorted=[...layers.labels].sort((a,b)=>(b.options.buildingArea||0)-(a.options.buildingArea||0));const allowed=new Set(zoom>=17?sorted:zoom>=16?sorted.slice(0,15):[]);const occupied=[];sorted.forEach(label=>{const element=label.getElement();if(!element)return;if(!allowed.has(label)){label.setOpacity(0);return}const rect=element.getBoundingClientRect();const overlap=occupied.some(other=>!(rect.right<other.left||rect.left>other.right||rect.bottom<other.top||rect.top>other.bottom));if(overlap){label.setOpacity(0)}else{label.setOpacity(1);occupied.push(rect)}})}vectorMap.on('zoomend moveend',refreshBuildingLabelsByArea);
function reservationAvailableOnDate(date){const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Seoul',hour:'2-digit',hourCycle:'h23'}).formatToParts(new Date());const today=kstDate();const currentHour=Number(parts.find(p=>p.type==='hour').value);return reservationFacilities.some(facility=>Array.from({length:12},(_,i)=>i+9).some(hour=>{if(date===today&&hour<=currentHour)return false;return !reservationFor(facility.id,date,hour)}))}renderReservationPanel=function(){if(!reservationFacilities.length)return;if(!reservationDate){reservationDate=reservationAvailableOnDate(reservationDates()[0])?reservationDates()[0]:reservationDates()[1]}const dates=reservationDates(),selected=reservationFacilities.find(f=>String(f.id)===String(selectedFacilityId));const ordered=selected?[selected,...reservationFacilities.filter(f=>String(f.id)!==String(selectedFacilityId))]:reservationFacilities;const content=reservationMode==='time'?renderTimeMode():`${ordered.map(f=>{const state=facilityAvailability(f);const collapsed=selected&&String(f.id)!==String(selectedFacilityId);return`<button class="facility-card ${state.full?'full':''} ${String(selectedFacilityId)===String(f.id)?'selected':''} ${collapsed?'collapsed':''}" data-facility="${f.id}"><div><strong>${escapeHtml(facilityName(f.id))}</strong><small>${escapeHtml(f.type)}</small></div><span>${state.full?'예약 불가':`${state.free}개 가능`}</span><em>${state.full?'':`다음 빈 시간 ${slotText(state.next)}`}</em></button>`}).join('')}${selected?renderFacilitySlots(selected):'<p class="reservation-hint">시설을 고르면 시간표가 보여요.</p>'}`;panel.querySelector('.panel-content').innerHTML=`<div class="reservation-dates">${dates.slice(0,3).map((date,i)=>{const ended=i===0&&!reservationAvailableOnDate(date);return`<button class="reservation-date ${date===reservationDate?'active':''}" data-date="${date}">${dateLabel(date,i)}${ended?'<small class="date-ended">오늘은 끝났어요</small>':`<small>${new Date(`${date}T12:00:00+09:00`).toLocaleDateString('ko-KR',{weekday:'short'})}</small>`}</button>`}).join('')}</div><div class="reservation-modes"><button class="reservation-mode ${reservationMode==='facilities'?'active':''}" data-mode="facilities">시설별로 보기</button><button class="reservation-mode ${reservationMode==='time'?'active':''}" data-mode="time">가능한 시간 보기</button></div><div class="reservation-body">${content}</div>`;panel.querySelectorAll('[data-date]').forEach(button=>button.addEventListener('click',()=>{reservationDate=button.dataset.date;selectedSlotHour=null;renderReservationPanel();updateReservationMap()}));panel.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{reservationMode=button.dataset.mode;renderReservationPanel()}));panel.querySelectorAll('[data-facility]').forEach(button=>button.addEventListener('click',()=>{selectedFacilityId=button.dataset.facility||null;selectedSlotHour=null;renderReservationPanel();updateReservationMap();const facility=reservationFacilities.find(item=>String(item.id)===String(selectedFacilityId));if(facility){vectorMap.flyTo(facility.center,17,{duration:.6});setTimeout(()=>panel.querySelector('.facility-slots')?.scrollIntoView({behavior:'smooth',block:'start'}),30)}}));panel.querySelectorAll('[data-slot-hour]').forEach(button=>button.addEventListener('click',()=>{selectedSlotHour=Number(button.dataset.slotHour);renderReservationPanel()}));panel.querySelectorAll('[data-time-facility]').forEach(button=>button.addEventListener('click',()=>{selectedFacilityId=button.dataset.timeFacility;selectedSlotHour=Number(button.dataset.timeHour);reservationMode='facilities';renderReservationPanel();updateReservationMap()}));panel.querySelector('#reserveSubmit')?.addEventListener('click',submitReservation);panel.querySelector('#reserveCancel')?.addEventListener('click',cancelSelectedReservation)};
let reservationDateAutoSelected=false;const baseReservationRender=renderReservationPanel;renderReservationPanel=function(){if(!reservationDateAutoSelected&&reservationFacilities.length){const dates=reservationDates();if(!reservationAvailableOnDate(dates[0]))reservationDate=dates[1];reservationDateAutoSelected=true}if(!selectedFacilityId&&reservationFacilities.length&&reservationMode==='facilities')selectedFacilityId=String(reservationFacilities[0].id);baseReservationRender()};panel.addEventListener('click',event=>{if(event.target.closest('[data-date]'))reservationDateAutoSelected=true});
reservationStatus=function(id,hour){if(myReservationFor(id,reservationDate,hour))return'mine';if(reservationFor(id,reservationDate,hour))return'taken';if(reservationDate===kstDate()&&hour<=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Asia/Seoul',hour:'2-digit',hourCycle:'h23'}).format(new Date())))return'past';return'available'};
function formatPlaceLabel(label){if(!label)return'';return String(label).replaceAll('중앙도서관','창파도서관').replaceAll('정보통신관','대구대학교 교수학습지원관').replaceAll('학생회관','제1학생회관')}
function shortEventPeriod(value){if(!value)return'';const dates=[...String(value).matchAll(/(\d{4})-(\d{2})-(\d{2})/g)].map(match=>`${Number(match[2])}.${Number(match[3])}`);if(dates.length===0)return String(value);const unique=[...new Set(dates)];return unique.length===1?unique[0]:`${unique[0]} ~ ${unique[unique.length-1]}`}
function compactSummary(title,summary){if(!summary)return'';const a=String(title).replace(/[\s\W]/g,'').toLowerCase();const b=String(summary).replace(/[\s\W]/g,'').toLowerCase();return a===b||a.includes(b)||b.includes(a)?'':summary}
renderNewsPanel=function(){if(!eventData)return;const selected=eventData.institutions.find(item=>item.id===selectedInstitutionId)||null;const sources=selected?[selected]:eventData.institutions;const events=sources.flatMap(institution=>institution.events.map(event=>({...event,institution}))).sort((a,b)=>{const rank={ongoing:0,upcoming:1,ended:2};return rank[eventStatus(a)]-rank[eventStatus(b)]||b.noticeDate.localeCompare(a.noticeDate)});panel.querySelector('.panel-content').innerHTML=`<div class="institution-pills"><button class="institution-pill ${!selected?'active':''}" data-institution="all">전체<b>${events.filter(event=>['ongoing','upcoming'].includes(eventStatus(event))).length}</b></button>${eventData.institutions.map(item=>`<button class="institution-pill ${selected?.id===item.id?'active':''}" data-institution="${item.id}">${shortInstitutionName(item)}<b>${activeEventCount(item)}</b></button>`).join('')}</div>${selected?`<div class="institution-card"><div><span>${language==='ko'?'기관':'Institution'}</span><h2>${escapeHtml(localizedName(selected.name))}</h2><p>${escapeHtml(selected.office.room||selected.office.building[language]||selected.office.building.ko)}</p></div><div class="institution-actions"><button class="office-jump" data-institution="${selected.id}">${language==='ko'?'사무실 위치':'Office location'} ↗</button><a href="${selected.website}" target="_blank" rel="noopener">${language==='ko'?'홈페이지':'Website'} ↗</a></div></div>`:''}<div class="event-list">${events.map(event=>{const status=eventStatus(event),place=event.location?.[language]||event.location?.ko||'',summary=compactSummary(event.title[language]||event.title.ko,event.summary[language]||event.summary.ko);return`<article class="event-card ${status}"><div class="event-card-top"><span class="event-status ${status}">${statusLabels[language][status]}</span><span class="event-institution-tag">${escapeHtml(shortInstitutionName(event.institution))}</span></div><h3>${escapeHtml(event.title[language]||event.title.ko)}</h3>${shortEventPeriod(event.period)?`<p class="event-meta">${escapeHtml(shortEventPeriod(event.period))}${place?` · ${escapeHtml(place)}`:''}</p>`:place?`<p class="event-meta">${escapeHtml(place)}</p>`:''}${summary?`<p class="event-summary">${escapeHtml(summary)}</p>`:''}${event.applicationDeadline?`<small class="event-deadline">${language==='ko'?'신청 마감':'Deadline'} · ${escapeHtml(event.applicationDeadline)}</small>`:''}<a class="event-source" href="${event.originalLink}" target="_blank" rel="noopener">${language==='ko'?'원문 보기':'View source'} ↗</a></article>`}).join('')}</div><p class="event-source-note">${language==='ko'?'출처 · 기관별 공식 홈페이지 공지사항':'Sources · Official institution notice pages'}</p>`;panel.querySelectorAll('[data-institution]').forEach(button=>button.addEventListener('click',()=>{selectedInstitutionId=button.dataset.institution==='all'?null:button.dataset.institution;renderNewsPanel()}));if(selected)panel.querySelector('.office-jump')?.addEventListener('click',()=>highlightOffice(selected))};
