reportCard=function(item){const state=reportState(item),count=reportCount(item),waiting=state==='전달 대기';return`<article class="report-card ${state==='수리완료'?'completed':''} ${waiting?'waiting':''}"><div class="report-card-top"><span class="report-status ${state==='수리완료'?'completed':waiting?'waiting':'checking'}">${state}</span><span>${escapeHtml(item.category)}</span><time>${pinTime(item.createdAt)}</time></div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(formatPlaceLabel(item.location?.label||'캠퍼스'))}</p><small>${escapeHtml(item.description)}</small>${waiting?reportOfficeBrief(item):''}<div class="report-card-bottom"><button class="reaction-button ${reactedPins.includes(item.id)?'reacted':''}" data-report-id="${item.id}" ${reactedPins.includes(item.id)?'disabled':''}>나도 겪었어요 <b>${count}</b></button>${!waiting&&state!=='수리완료'?`<em>전달까지 ${Math.max(0,6-count)}명</em>`:''}${waiting?'<em>행정실 전달 대기</em>':''}</div></article>`};
formatPlaceLabel=function(label){if(!label)return'';return String(label).replaceAll('중앙도서관','창파도서관').replaceAll('제1제1학생회관','제1학생회관').replace(/(?<!제1)학생회관/g,'제1학생회관').replaceAll('정보통신관','대구대학교 교수학습지원관')};lostText=function(item,field){let value;if(language==='en'&&item[`${field}En`])value=item[`${field}En`];else if(language==='en'&&field==='title'&&item.category)value=`${item.kind==='found'?'Found':'Lost'} ${itemEnglish[item.category]||'item'}`;else if(language==='en'&&field==='description')value=`A ${itemEnglish[item.category]||'item'} ${item.kind==='found'?'was found':'was lost'} near ${item.location?.label||'campus'}`;else value=item[field]||'';return field==='description'?formatPlaceLabel(value):value};function shortDeadline(value){if(!value)return'';return String(value).replace(/(\d{4})-(\d{2})-(\d{2})/g,(_,y,m,d)=>`${Number(m)}.${Number(d)}`)}function eventTitleKey(value){return String(value||'').toLowerCase().replace(/202\d|학년도|실시|안내|경품|있음|[^a-z0-9가-힣]/g,'')}function dedupeEventLists(data){data.institutions.forEach(institution=>{const ordered=[...institution.events].sort((a,b)=>String(b.noticeDate).localeCompare(String(a.noticeDate)));const kept=[];for(const event of ordered){const key=eventTitleKey(event.title.ko);const duplicate=kept.some(old=>old.originalLink===event.originalLink||(key&&eventTitleKey(old.title.ko)===key));if(!duplicate){event.applicationDeadline=shortDeadline(event.applicationDeadline);if(event.id==='rise-223586')event.period=null;kept.push(event)}}institution.events=kept})}
dedupeEventLists=function(data){data.institutions.forEach(institution=>{const ordered=[...institution.events].sort((a,b)=>String(b.noticeDate).localeCompare(String(a.noticeDate)));const kept=[];for(const event of ordered){const key=eventTitleKey(event.title.ko);const sameLink=event.originalLink===kept.find(old=>old.originalLink===event.originalLink)?.originalLink&&!event.linkNote&&!kept.find(old=>old.originalLink===event.originalLink)?.linkNote;const duplicate=event.linkNote?false:(sameLink||kept.some(old=>{const oldKey=eventTitleKey(old.title.ko);return oldKey&&oldKey===key}));if(!duplicate){event.applicationDeadline=shortDeadline(event.applicationDeadline);if(event.id==='rise-223586')event.period=null;kept.push(event)}}institution.events=kept})};
const smallLanguage={ko:{all:'전체',lounge:'라운지',cafe:'카페·식당',convenience:'편의점',other:'기타',lost:'잃어버림',found:'주움',facility:'편의시설',report:'제보',news:'소식',sports:'운동장',weekdays:['월','화','수','목','금'],weather:{맑음:'맑음',구름:'구름',안개:'안개',비:'비',눈:'눈',날씨:'날씨'}},en:{all:'All',lounge:'Lounge',cafe:'Cafe·Food',convenience:'Convenience',other:'Other',lost:'Lost',found:'Found',facility:'Facilities',report:'Report',news:'News',sports:'Sports',weekdays:['Mon','Tue','Wed','Thu','Fri'],weather:{맑음:'Clear',구름:'Cloudy',안개:'Foggy',비:'Rain',눈:'Snow',날씨:'Weather'}}};const categoryEnglish={이어폰:'earbuds',학생증:'student ID',지갑:'wallet',우산:'umbrella',텀블러:'tumbler',충전기:'charger',필통:'pencil case',기타:'item',콘센트:'outlet',빔프로젝터:'projector',에어컨:'air conditioner',의자:'chair',와이파이:'Wi-Fi',문:'door',엘리베이터:'elevator'};function syncSmallLanguage(){const text=smallLanguage[language];Object.keys(spotTypes).forEach(key=>spotTypes[key]=text[key]);lostKinds.lost=text.lost;lostKinds.found=text.found;document.querySelector('.institution-pill[data-institution="all"]')?.firstChild&&(document.querySelector('.institution-pill[data-institution="all"]').firstChild.nodeValue=`${text.all}`)}function itemCategoryText(value){return language==='en'?categoryEnglish[value]||value:value}function placeLabelText(label){if(!label)return'';if(language==='en'){const map={'창파도서관 근처':'near Changpa Library','제1학생회관 앞':'in front of Student Center 1','제1학생회관 2층':'Student Center 1, 2F','사회과학대학 1호관':'College of Social Sciences Building 1','인문대학 1,2호관':'Humanities Buildings 1 and 2','공과대학 7호관':'College of Engineering Building 7','재활과학대학':'College of Rehabilitation Sciences','조형예술대학 2호관':'College of Fine Arts Building 2','생명환경대학 2호관':'College of Life and Environment Building 2','공과대학본부동':'College of Engineering Administration Building','경상대학관':'College of Economics and Business Administration','정보통신관':'Daegu University Center for Teaching and Learning'};return map[label]||label}return formatPlaceLabel(label)}formatPlaceLabel=placeLabelText;lostText=function(item,field){if(field==='description'){const category=categoryEnglish[item.category]||'item';const place=placeLabelText(item.location?.label||'campus');if(language==='en')return`A ${category} ${item.kind==='found'?'was found':'was lost'} ${place.startsWith('near')?place:`at ${place}`}.`;return formatPlaceLabel(item.description||'')}if(language==='en'&&field==='title')return`${item.kind==='found'?'Found':'Lost'} ${categoryEnglish[item.category]||'item'}`;return item[field]||''};shortInstitutionName=function(item){if(language==='en')return({rise:'RISE','du-huss':'HUSS',library:'Changpa Library',university:'Main Building',aisw:'SW'})[item.id]||localizedName(item.name);return({rise:'RISE','du-huss':'HUSS',library:'창파도서관',university:'본관',aisw:'SW'})[item.id]||localizedName(item.name)};const originalSpotHoursState=spotHoursState;spotHoursState=function(spot){const state=originalSpotHoursState(spot);if(state)state.dayLabel=smallLanguage[language].weekdays.join('·');return state};weatherLabel=function(code){if(code===0)return smallLanguage[language].weather.맑음;if(code<=3)return smallLanguage[language].weather.구름;if(code<=48)return smallLanguage[language].weather.안개;if(code<=67||code>=80)return smallLanguage[language].weather.비;if(code<=77)return smallLanguage[language].weather.눈;return smallLanguage[language].weather.날씨};syncSmallLanguage();new MutationObserver(()=>{syncSmallLanguage();if(activePanel==='news')renderNewsPanel();if(activePanel==='facilities')renderSpotsPanel();if(activePanel==='lost')renderLostPanel();if(activePanel==='report')renderReportPanel()}).observe(document.documentElement,{attributes:true,attributeFilter:['data-language']});
renderLostPanel=function(){const items=lostItems().filter(item=>lostFilter==='all'||item.kind===lostFilter).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt));panel.querySelector('.panel-content').innerHTML=`<div class="lost-filters"><button class="lost-filter ${lostFilter==='all'?'active':''}" data-lost-filter="all">${smallLanguage[language].all}</button><button class="lost-filter ${lostFilter==='lost'?'active':''}" data-lost-filter="lost">${smallLanguage[language].lost}</button><button class="lost-filter ${lostFilter==='found'?'active':''}" data-lost-filter="found">${smallLanguage[language].found}</button></div><div class="lost-count">${items.length}${language==='en'?' posts':'개'}</div><div class="lost-list">${items.map(item=>`<button class="lost-card" data-lost-id="${item.id}"><div class="lost-card-top"><span class="lost-kind ${item.kind}">${lostKinds[item.kind]||item.kind}</span><span>${escapeHtml(itemCategoryText(item.category||'기타'))}</span><time>${pinTime(item.createdAt)}</time></div><h3>${escapeHtml(lostText(item,'title'))}</h3><p>${escapeHtml(placeLabelText(item.location?.label||'캠퍼스'))}</p><small>${escapeHtml(lostText(item,'description'))}</small></button>`).join('')}</div>`;panel.querySelectorAll('[data-lost-filter]').forEach(button=>button.addEventListener('click',()=>{lostFilter=button.dataset.lostFilter;renderLostPanel();renderPins()}));panel.querySelectorAll('[data-lost-id]').forEach(card=>card.addEventListener('click',()=>{const item=items.find(entry=>entry.id===card.dataset.lostId);if(item)showLostItem(item)}))};reportCard=function(item){const state=reportState(item),count=reportCount(item),waiting=state==='전달 대기';return`<article class="report-card ${state==='수리완료'?'completed':''} ${waiting?'waiting':''}"><div class="report-card-top"><span class="report-status ${state==='수리완료'?'completed':waiting?'waiting':'checking'}">${language==='en'?(state==='전달 대기'?'Needs delivery':state==='수리완료'?'Completed':state==='확인중'?'Checking':'Received'):state}</span><span>${escapeHtml(itemCategoryText(item.category))}</span><time>${pinTime(item.createdAt)}</time></div><h3>${escapeHtml(item.title)}</h3><p>${escapeHtml(placeLabelText(item.location?.label||'캠퍼스'))}</p><small>${escapeHtml(item.description)}</small>${waiting?reportOfficeBrief(item):''}<div class="report-card-bottom"><button class="reaction-button ${reactedPins.includes(item.id)?'reacted':''}" data-report-id="${item.id}" ${reactedPins.includes(item.id)?'disabled':''}>${language==='en'?'I experienced this too':'나도 겪었어요'} <b>${count}</b></button>${!waiting&&state!=='수리완료'?`<em>${language==='en'?`${Math.max(0,6-count)} more to deliver`:`전달까지 ${Math.max(0,6-count)}명`}</em>`:''}${waiting?`<em>${language==='en'?'Waiting for office delivery':'행정실 전달 대기'}</em>`:''}</div></article>`};syncSmallLanguage();
formatPlaceLabel=function(label){if(!label)return'';return String(label).replaceAll('중앙도서관','창파도서관').replaceAll('제1제1학생회관','제1학생회관').replace(/(?<!제1)학생회관/g,'제1학생회관').replaceAll('정보통신관','대구대학교 교수학습지원관')};placeLabelText=function(label){if(!label)return'';if(language==='en'){const map={'창파도서관 근처':'near Changpa Library','제1학생회관 앞':'in front of Student Center 1','제1학생회관 2층':'Student Center 1, 2F','사회과학대학 1호관':'College of Social Sciences Building 1','인문대학 1,2호관':'Humanities Buildings 1 and 2','공과대학 7호관':'College of Engineering Building 7','재활과학대학':'College of Rehabilitation Sciences','조형예술대학 2호관':'College of Fine Arts Building 2','생명환경대학 2호관':'College of Life and Environment Building 2','공과대학본부동':'College of Engineering Administration Building','경상대학관':'College of Economics and Business Administration','정보통신관':'Daegu University Center for Teaching and Learning'};return map[label]||label}return formatPlaceLabel(label)};
